AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) 
    : AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined[3];
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];
    AP4_String name;

    // Read pre-defined values
    stream.ReadBE(pre_defined, sizeof(pre_defined));
    stream.ReadBE(&handler_type, sizeof(handler_type));
    stream.ReadBE(reserved, sizeof(reserved));

    // Read name if space allows
    AP4_UI32 name_size = size - (sizeof(AP4_UI32)*7 + 1);
    if (name_size > 0) {
        AP4_UI08 name_length;
        stream.ReadBE(&name_length);
        if (name_length > 0 && name_length <= name_size - 1) {
            AP4_UI08* name_bytes = new AP4_UI08[name_length + 1];
            stream.Read(name_bytes, name_length);
            name_bytes[name_length] = '\0';
            name = AP4_String(reinterpret_cast<char*>(name_bytes));
            delete[] name_bytes;
        } else {
            // Invalid or zero-length string, name remains empty
        }
    }

    // Initialize the handler name
    m_HandlerType = handler_type;
    m_HandlerName = name;
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream)
    : AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined[3];
    AP4_UI08  handler_type[4];
    AP4_UI32  reserved[2];

    stream.ReadUI32(pre_defined);
    stream.ReadUI32(&pre_defined[1]);
    stream.ReadUI32(&pre_defined[2]);
    stream.ReadBytes(handler_type, 4);
    stream.ReadUI32(reserved);
    stream.ReadUI32(&reserved[1]);

    AP4_UI08 name_length = 0;
    if (size > 22) {
        name_length = stream.ReadUI08();
        if (name_length > 0) {
            m_name.SetLength(name_length);
            stream.ReadBytes(m_name.Use(), name_length);

            // Convert Pascal string to C string
            if (m_name[0] == 0) {
                m_name.Erase();
            } else if (m_name[name_length - 1] != '\0') {
                m_name += '\0';
            }
        }
    }
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) :
    AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined[3];
    AP4_UI08  handler_type[4];
    AP4_UI32  reserved[2];
    AP4_Size  name_size;

    // read the pre-defined fields
    stream.ReadBE(pre_defined, sizeof(pre_defined));
    stream.ReadBE(handler_type, sizeof(handler_type));
    stream.ReadBE(reserved, sizeof(reserved));

    // read the name size
    AP4_UI32 name_size;
    stream.ReadBE(&name_size, sizeof(name_size));

    // compute the name size
    AP4_Size available_size = m_Size - (stream.Tell() - m_HeaderStart);
    if (name_size > available_size) name_size = available_size;

    // read the name
    if (name_size > 0) {
        m_Name = new AP4_UI08[name_size];
        stream.ReadBE(m_Name, name_size);

        // if the name is a pascal string, convert to c string
        if (m_Name[0] == 0) {
            AP4_Size i;
            for (i = 1; i < name_size; i++) {
                if (m_Name[i] == 0) break;
            }
            if (i > 1) {
                AP4_Size length = i - 1;
                memmove(m_Name, m_Name + 1, length);
                m_Name[length] = 0;
            }
        }
    }
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) :
    AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined[3];
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];
    AP4_UI16  name_length;

    stream.ReadBE(pre_defined, sizeof(pre_defined));
    stream.ReadBE(&handler_type, sizeof(handler_type));
    stream.ReadBE(reserved, sizeof(reserved));

    if (m_size > 24) {
        stream.ReadBE(&name_length, sizeof(name_length));
        if (name_length > 0) {
            if (name_length > m_size - 24 - sizeof(name_length)) {
                name_length = m_size - 24 - sizeof(name_length);
            }
            m_name.SetLength(name_length);
            stream.ReadBE(m_name.UseData(), m_name.Length());
            if (m_name.Length() > 0 && m_name[m_name.Length()-1] == '\0') {
                m_name.SetLength(m_name.Length()-1);
            }
        }
    }

    // Convert handler type to a string
    for (unsigned int i=0; i<4; i++) {
        m_handler_type.PushBack((AP4_UI08)((handler_type >> (24 - i*8)) & 0xFF));
    }
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream)
    : AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  predefined;
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];
    AP4_String  name;

    // read the predefined and handler type
    stream.ReadBE(&predefined, sizeof(predefined));
    stream.ReadBE(&handler_type, sizeof(handler_type));
    stream.ReadBE(reserved, sizeof(reserved));

    // check if we have space for the name
    if (m_size < stream.Tell() + 1) {
        return;
    }

    // read the name
    AP4_UI08 name_length;
    stream.ReadBE(&name_length, sizeof(name_length));
    if (name_length > 0) {
        char* name_chars = new char[name_length + 1];
        stream.Read(name_chars, name_length);
        name_chars[name_length] = '\0';
        name = AP4_String(name_chars);
        delete[] name_chars;
    } else {
        // read null-terminated string if name_length is 0
        char buffer[256];
        size_t len = 0;
        while (len < sizeof(buffer) - 1 && stream.Tell() < m_size) {
            char c;
            stream.Read(&c, 1);
            if (c == '\0') break;
            buffer[len++] = c;
        }
        buffer[len] = '\0';
        name = AP4_String(buffer);
    }

    // additional logic may go here for internal object setup
}
